INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melobot: A Last Song', 'Immerse yourself in the dreamlike world of Melobot - A Last Song, an adventure, action, and rhythm game that thrusts you into a heroic quest to save a planet plagued by a strange disease. You play as Melobot, a lovable musical robot originally designed for peace, and awaken to a vital mission: revive the planet’s unique flora by recreating their songs and overcoming the challenges set by powerful guardians.' FROM games WHERE igdb_id = 199252 ON CONFLICT (game_id, language_code) DO NOTHING;
