INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urban Strife', 'Urban Strife is an old-school TBS, where you lead a team of makeshift, slightly deranged militia in an effort to keep the small community of Urban Shelter alive, amidst a zombie pandemic. With what’s left of human civilization divided into factions fighting over the scraps, you will need to broker alliances and fight factions wars, fortify and rebuild your community and forge a future against the ever-present threat of the zombie horde.' FROM games WHERE igdb_id = 134954 ON CONFLICT (game_id, language_code) DO NOTHING;
